-- T1 pins its snapshot. T2's update is invisible to T1's re-read,
-- but T2's insert can appear as a phantom.
-- T1:
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
BEGIN;
SELECT balance FROM accounts WHERE id = 1; -- returns 100
-- (concurrently) T2: UPDATE accounts SET balance=200 WHERE id=1; COMMIT;
SELECT balance FROM accounts WHERE id = 1; -- still returns 100 under RR
-- (concurrently) T2: INSERT INTO accounts(id,balance) VALUES (2, 50); COMMIT;
SELECT COUNT(*) FROM accounts WHERE balance >= 50; -- may return different count
COMMIT;
